import Foundation

/// One generated file: a repository-relative path and its full contents.
public struct GeneratedFile: Equatable, Sendable {
    public let path: String
    public let contents: String

    public init(path: String, contents: String) {
        self.path = path
        self.contents = contents
    }
}

/// Writes the token model as Swift, in three files:
///
/// - `QeetrixFoundationTokens.swift` — the public, typed token API: the `QeetrixColor` and
///   `QeetrixShadow` cases, the typography roles, and every value that is the same in both colour
///   schemes (space, sizes, radii, borders, focus, opacity, icon metrics, density, motion, faces).
/// - `Qeetrix<Scheme>Tokens.swift` — one internal table per colour scheme with its colour and shadow
///   values. Foundations pick the table from the SwiftUI environment.
///
/// Every declaration carries its token path and CSS variable, so a reader can always find the web
/// definition it came from.
public struct TokenEmitter {
    let model: TokenModel
    let stylesheet: Stylesheet
    let provenance: Provenance
    let fonts: [FontSpec]

    public static let directory = "Sources/Qeetrix/Tokens/Generated"

    public init(model: TokenModel, stylesheet: Stylesheet, provenance: Provenance, fonts: [FontSpec]) {
        self.model = model
        self.stylesheet = stylesheet
        self.provenance = provenance
        self.fonts = fonts
    }

    var package: Provenance.Package {
        (try? provenance.package(Provenance.tokensPackage)) ?? Provenance.Package(name: "?", version: "?", gitHead: "", integrity: "")
    }

    var header: String {
        """
        // GENERATED by qeetrix-gen from \(package.name) \(package.version) (DTCG build) — do not edit.
        // Change the tokens upstream, bump Upstream/pins.json, run Scripts/sync-upstream.sh, then Scripts/generate.sh.


        """
    }

    var base: TokenContext { model.source.defaultContext }

    public func files() throws -> [GeneratedFile] {
        [try foundation()] + (try model.source.colorSchemes.map(schemeFile))
    }

    static func schemeTypeName(_ scheme: String) -> String {
        "Qeetrix" + scheme.capitalizedFirst + "Tokens"
    }

    // MARK: Helpers

    func doc(_ token: ResolvedToken, _ extra: String? = nil, indent: String = "    ") -> String {
        let declared = Stylesheet.properties(token).contains { stylesheet.root[$0.name] != nil }
        let source = declared ? "`\(token.dotted)` · `\(token.cssName)`" : "`\(token.dotted)`"
        let alias = token.sources[base]?.alias.map { " (\($0))" } ?? ""
        guard let extra else { return "\(indent)/// \(source)\(alias)\n" }
        return "\(indent)/// \(source)\(alias)\n\(indent)///\n\(indent)/// \(extra)\n"
    }

    func dimension(_ token: ResolvedToken) throws -> Double {
        guard case let .dimension(value) = token.value(base) else { throw GeneratorError("\(token.dotted): expected a dimension.") }
        return value
    }

    func number(_ token: ResolvedToken) throws -> Double {
        guard case let .number(value) = token.value(base) else { throw GeneratorError("\(token.dotted): expected a number.") }
        return value
    }

    func cgFloats(_ group: TokenGroup) throws -> String {
        try model.tokens(group).map { token in
            let value = try dimension(token)
            return doc(token, "\(swiftNumber(value)) pt")
                + "    public static let \(SwiftNames.declaration(token.name)): CGFloat = \(swiftNumber(value))\n"
        }.joined(separator: "\n")
    }

    func rgba(_ color: ColorMath.EncodedColor) -> String {
        "QeetrixRGBA(.\(color.space.rawValue), \(swiftNumber(color.red)), \(swiftNumber(color.green)), \(swiftNumber(color.blue)), \(swiftNumber(color.alpha)))"
    }

    func describe(_ color: ColorMath.EncodedColor) -> String {
        var text = color.hex
        if color.space == .displayP3 { text += " (Display P3\(color.gamutMapped ? ", gamut-mapped" : ""))" }
        return text
    }

    // MARK: Foundation file

    func foundation() throws -> GeneratedFile {
        let sections = [
            try colorCases(),
            try shadowCases(),
            try dimensions(),
            try density(),
            try motion(),
            try typography(),
            try fontFamilies(),
        ]
        return GeneratedFile(
            path: "\(Self.directory)/QeetrixFoundationTokens.swift",
            contents: header + "import CoreGraphics\nimport Foundation\n\n" + sections.joined(separator: "\n"))
    }

    func colorCases() throws -> String {
        let schemes = model.source.colorSchemes
        let body = try model.tokens(.color).map { token in
            let values = try schemes.map { scheme -> String in
                guard case let .color(color) = token.value(TokenContext(colorScheme: scheme, density: base.density)) else {
                    throw GeneratorError("\(token.dotted): expected a colour.")
                }
                return "\(scheme.capitalizedFirst) \(describe(color))"
            }
            return doc(token, values.joined(separator: " · "))
                + "    case \(SwiftNames.declaration(token.name)) = \(swiftString(token.dotted))\n"
        }.joined(separator: "\n")
        return """
            /// The semantic colours: every `color.*` token of `@qeetrix/tokens`. Raw values are the token
            /// paths. A colour resolves to its light or dark value from the SwiftUI environment; palette
            /// primitives are deliberately not available.
            public enum QeetrixColor: String, CaseIterable, Sendable {
            \(body)}

            """
    }

    func shadowCases() throws -> String {
        let body = model.tokens(.shadow).map { token in
            doc(token) + "    case \(SwiftNames.declaration(token.name)) = \(swiftString(token.dotted))\n"
        }.joined(separator: "\n")
        return """
            /// The shadows (`shadow.*`): layered, and different per colour scheme. Qeetrix puts shadows only
            /// on floating layers (design rules §12): menus, popovers, toasts and dialogs.
            public enum QeetrixShadow: String, CaseIterable, Sendable {
            \(body)}

            """
    }

    func dimensions() throws -> String {
        let opacity = try model.tokens(.opacity).map { token in
            doc(token) + "    public static let \(SwiftNames.declaration(token.name)): Double = \(swiftNumber(try number(token)))\n"
        }.joined(separator: "\n")
        let iconSizes = try model.tokens(.iconSize).map { token in
            let value = try dimension(token)
            return doc(token, "\(swiftNumber(value)) pt")
                + "    public static let \(SwiftNames.declaration(token.name)) = QeetrixIconSize(\(swiftNumber(value)))\n"
        }.joined(separator: "\n")
        let iconStrokes = try model.tokens(.iconStroke).map { token in
            let value = try number(token)
            return doc(token, "\(swiftNumber(value)) units of the 24-unit icon grid")
                + "    public static let \(SwiftNames.declaration(token.name)) = QeetrixIconStroke(\(swiftNumber(value)))\n"
        }.joined(separator: "\n")
        return """
            /// The spacing scale (`space.inset.*` inside containers, `space.gap.*` between siblings,
            /// `space.layout.*` between sections), in points. The form gap follows the density:
            /// ``QeetrixDensity/spaceFormGap``.
            public enum QeetrixSpace {
            \(try cgFloats(.space))}

            /// Sizes that are not a density or an icon size (`size.target.*`), in points.
            public enum QeetrixSize {
            \(try cgFloats(.size))}

            /// Corner radii (`radius.*`), in points. `chip` and `full` are pill and circle radii: use
            /// `Capsule` or `Circle`.
            public enum QeetrixRadius {
            \(try cgFloats(.radius))}

            /// Border widths (`border.width.*`), in points. `accent` is the Ember bar that marks the current
            /// item and the intent line on top of a dialog.
            public enum QeetrixBorderWidth {
            \(try cgFloats(.borderWidth))}

            /// Focus frame geometry (`focus.ring.*`), in points. The frame's colour is
            /// `QeetrixColor.borderFocus`.
            public enum QeetrixFocus {
            \(try cgFloats(.focus))}

            /// Opacities (`opacity.*`).
            public enum QeetrixOpacity {
            \(opacity)}

            extension QeetrixIconSize {
            \(iconSizes)}

            extension QeetrixIconStroke {
            \(iconStrokes)}

            """
    }

    /// `size.control.*`, `size.row` and `space.form.gap`: one property per token, one case per
    /// density context of the resolver.
    func density() throws -> String {
        let densities = model.source.densities
        var body = try densities.map { "    case \(SwiftNames.declaration(try SwiftNames.identifier([$0], context: "density \($0)")))\n" }
            .joined()
        for token in model.tokens(.density) {
            body +=
                "\n" + doc(token, "In points, per density.")
                + "    public var \(SwiftNames.declaration(token.name)): CGFloat {\n        switch self {\n"
            for density in densities {
                guard case let .dimension(points) = token.value(TokenContext(colorScheme: base.colorScheme, density: density)) else {
                    throw GeneratorError("\(token.dotted) (\(density)): expected a dimension.")
                }
                body += "        case .\(try SwiftNames.identifier([density], context: token.dotted)): \(swiftNumber(points))\n"
            }
            body += "        }\n    }\n"
        }
        return """
            /// The densities (`@qeetrix/tokens`' density modifier) and the sizes each sets. On the web a
            /// region sets one with `data-qx-density`; here a view sets one with `qeetrixDensity(_:)`.
            public enum QeetrixDensity: String, CaseIterable, Sendable {
            \(body)}

            """
    }

    func motion() throws -> String {
        let durations = model.tokens(.duration).map { token -> String in
            guard case let .duration(seconds) = token.value(base) else { return "" }
            return doc(token, "\(swiftNumber(seconds * 1000)) ms")
                + "    public static let \(SwiftNames.declaration(token.name)) = QeetrixDuration(seconds: \(swiftNumber(seconds)))\n"
        }.joined(separator: "\n")
        let easings = model.tokens(.easing).map { token -> String in
            guard case let .easing(points) = token.value(base) else { return "" }
            return doc(token)
                + "    public static let \(SwiftNames.declaration(token.name)) = QeetrixEasing(\(points.map(swiftNumber).joined(separator: ", ")))\n"
        }.joined(separator: "\n")

        var springNames: [String] = []
        for token in model.tokens(.spring) where !springNames.contains(token.path[2]) { springNames.append(token.path[2]) }
        let springs = try springNames.map { spring -> String in
            let parts = model.tokens(.spring).filter { $0.path[2] == spring }
            guard Set(parts.map { $0.path[3] }) == ["stiffness", "damping-ratio"],
                let stiffness = parts.first(where: { $0.path[3] == "stiffness" }),
                let damping = parts.first(where: { $0.path[3] == "damping-ratio" })
            else { throw GeneratorError("motion.spring.\(spring): needs exactly stiffness and damping-ratio.") }
            let name = SwiftNames.declaration(try SwiftNames.identifier([spring], context: "motion.spring.\(spring)"))
            return
                "    /// `motion.spring.\(spring).*`: stiffness \(swiftNumber(try number(stiffness))), damping ratio \(swiftNumber(try number(damping))), mass 1.\n"
                + "    public static let \(name) = QeetrixSpring(stiffness: \(swiftNumber(try number(stiffness))), dampingRatio: \(swiftNumber(try number(damping))))\n"
        }.joined(separator: "\n")

        // Reduce Motion: tokens.css's @media (prefers-reduced-motion: reduce) block; the DTCG build has no
        // context for it.
        let reduced = try model.tokens(.duration).map { token -> Double in
            guard let raw = stylesheet.reducedMotion[token.cssName] else {
                throw GeneratorError("\(token.dotted): tokens.css sets no reduced-motion value for it; iOS needs one for Reduce Motion.")
            }
            return try CSSValues.duration(try CSSParser.parse(raw, context: token.cssName), context: token.cssName)
        }
        guard let reducedDuration = reduced.first, reduced.allSatisfy({ $0 == reducedDuration }) else {
            throw GeneratorError("tokens.css reduces the motion durations to different values; QeetrixMotion maps one.")
        }
        return """
            extension QeetrixDuration {
            \(durations)}

            extension QeetrixEasing {
            \(easings)}

            extension QeetrixSpring {
            \(springs)}

            extension QeetrixMotion {
                /// What every `motion.duration.*` becomes under Reduce Motion: \(swiftNumber(reducedDuration * 1000)) ms, from tokens.css's
                /// `@media (prefers-reduced-motion: reduce)` block.
                public static let reducedDuration = QeetrixDuration(seconds: \(swiftNumber(reducedDuration)))
            }

            """
    }

    func typography() throws -> String {
        var weights: [(name: String, value: Double)] = []
        let weightBody = try model.tokens(.fontWeight).map { token -> String in
            let value = try number(token)
            weights.append((token.name, value))
            return "    /// `\(token.dotted)`: \(swiftNumber(value)), a weight the type roles use.\n"
                + "    public static let \(SwiftNames.declaration(token.name)) = QeetrixFontWeight(\(swiftNumber(value)))\n"
        }.joined(separator: "\n")
        var geometries: [String: String] = [:]
        let geometryBody = try model.tokens(.fontGeometry).map { token -> String in
            let value = try number(token)
            geometries[token.dotted] = token.name
            return doc(token) + "    public static let \(SwiftNames.declaration(token.name)) = QeetrixFontGeometry(\(swiftNumber(value)))\n"
        }.joined(separator: "\n")

        let families = Dictionary(uniqueKeysWithValues: fonts.map { ($0.webFamily, $0) })
        var cases: [String] = []
        var specs: [String] = []
        for token in model.tokens(.textRole) {
            guard case let .typography(type) = token.value(base) else { throw GeneratorError("\(token.dotted): expected typography.") }
            guard let family = families[type.family] else {
                throw GeneratorError("\(token.dotted): no bundled font for \(type.family) (bundled: \(families.keys.sorted())).")
            }
            guard let weightName = weights.first(where: { $0.value == type.weight })?.name else {
                throw GeneratorError("\(token.dotted): weight \(type.weight) is not on the primitive.font.weight scale.")
            }
            // The letter style the role names. A family without a GEOM axis (Fira Code) has none to
            // set, as the web's `font-variation-settings: "GEOM" …` does nothing there.
            guard let geometryName = geometries[type.geometry] else {
                throw GeneratorError("\(token.dotted): names \(type.geometry), which is not a generated font.geometry token.")
            }
            let hasGeometry = family.info.axes.contains { $0.tag == "GEOM" }
            let geometry = hasGeometry ? ".\(geometryName)" : "nil"
            let role = token.path.dropFirst().joined(separator: ".")
            cases.append(
                doc(
                    token,
                    "\(type.family), \(swiftNumber(type.size)) pt, weight \(swiftNumber(type.weight)), line height \(swiftNumber(type.lineHeightLength)) pt\(type.letterSpacing == 0 ? "" : ", tracked \(swiftNumber(type.letterSpacing)) pt")\(hasGeometry ? ", letter style \(type.geometry)" : "")."
                )
                    + "    case \(SwiftNames.declaration(token.name)) = \(swiftString(role))\n")
            specs.append(
                "        case .\(token.name):\n            QeetrixTextRoleTokens(\n                family: .\(family.family), size: \(swiftNumber(type.size)), weight: .\(weightName),\n                lineHeight: \(swiftNumber(type.lineHeightLength)) / \(swiftNumber(type.size)), letterSpacing: \(swiftNumber(type.letterSpacing)), geometry: \(geometry))\n"
            )
        }

        return """
            extension QeetrixFontWeight {
            \(weightBody)
                /// The weight scale, lightest first.
                public static let scale: [QeetrixFontWeight] = [\(weights.map { ".\($0.name)" }.joined(separator: ", "))]
            }

            /// Positions on Qeet Sans's GEOM axis, the letter style: `body` is the A11y forms, `heading` Base,
            /// `display` Geo.
            extension QeetrixFontGeometry {
            \(geometryBody)}

            /// The Qeetrix typography roles (`typography.*`). Raw values are the role paths (`body.md`).
            public enum QeetrixTextRole: String, CaseIterable, Sendable {
            \(cases.joined(separator: "\n"))
                /// The role's token values, and its letter style.
                public var tokens: QeetrixTextRoleTokens {
                    switch self {
            \(specs.joined())        }
                }
            }

            """
    }

    func fontFamilies() throws -> String {
        var cases: [String] = []
        var faces: [String] = []
        for font in fonts {
            cases.append(
                "    /// \(font.webFamily) on the web: \(font.info.familyName), \(font.info.version), from \(font.package) `\(font.source)`.\n    case \(SwiftNames.declaration(font.family))\n"
            )
            let axes = font.info.axes.map {
                "QeetrixFontAxis(tag: \(swiftString($0.tag)), minimum: \(swiftNumber($0.minimum)), defaultValue: \(swiftNumber($0.defaultValue)), maximum: \(swiftNumber($0.maximum)))"
            }
            faces.append(
                """
                        case .\(font.family):
                            QeetrixFontFace(
                                resourceName: \(swiftString(font.resourceName)),
                                postScriptName: \(swiftString(font.info.postScriptName)),
                                familyName: \(swiftString(font.info.familyName)),
                                webFamily: \(swiftString(font.webFamily)),
                                axes: [
                                    \(axes.joined(separator: ",\n                    "))
                                ])

                """)
        }
        return """
            /// The bundled typefaces: the web's own fonts, as the TTFs `@qeetrix/tokens` ships for native platforms.
            public enum QeetrixFontFamily: String, CaseIterable, Sendable {
            \(cases.joined(separator: "\n"))
                /// The bundled font file and its variation axes, as read from the font at generation time.
                public var face: QeetrixFontFace {
                    switch self {
            \(faces.joined())        }
                }
            }

            """
    }

    // MARK: Colour-scheme files

    func schemeFile(_ scheme: String) throws -> GeneratedFile {
        let context = TokenContext(colorScheme: scheme, density: base.density)
        var colorCases = ""
        for token in model.tokens(.color) {
            guard case let .color(value) = token.value(context) else {
                throw GeneratorError("\(token.dotted) (\(scheme)): expected a colour.")
            }
            colorCases += "        case .\(token.name): \(rgba(value))\n"
        }
        var shadowCases = ""
        for token in model.tokens(.shadow) {
            guard case let .shadow(layers) = token.value(context) else {
                throw GeneratorError("\(token.dotted) (\(scheme)): expected a shadow.")
            }
            if layers.isEmpty {
                shadowCases += "        case .\(token.name): []\n"
                continue
            }
            shadowCases += "        case .\(token.name):\n            [\n"
            for layer in layers {
                shadowCases +=
                    "                QeetrixShadowLayer(x: \(swiftNumber(layer.x)), y: \(swiftNumber(layer.y)), blur: \(swiftNumber(layer.blur)), spread: \(swiftNumber(layer.spread)), isInset: \(layer.inset), rgba: \(rgba(layer.color))),\n"
            }
            shadowCases += "            ]\n"
        }
        let typeName = Self.schemeTypeName(scheme)
        return GeneratedFile(
            path: "\(Self.directory)/\(typeName).swift",
            contents: header + """
                /// The `\(scheme)` colour scheme's colour and shadow values (`\(scheme).tokens.json`). Internal: views
                /// read them through `QeetrixColor` and `QeetrixShadow`, which choose the scheme from the SwiftUI
                /// environment.
                enum \(typeName) {
                    static func color(_ color: QeetrixColor) -> QeetrixRGBA {
                        switch color {
                \(colorCases)        }
                    }

                    static func shadow(_ shadow: QeetrixShadow) -> [QeetrixShadowLayer] {
                        switch shadow {
                \(shadowCases)        }
                    }
                }

                """)
    }
}

extension String {
    /// The string with its first character upper-cased: `button` → `Button`.
    var capitalizedFirst: String { prefix(1).uppercased() + dropFirst() }
}
